import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.abs

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st1 = StringTokenizer(br.readLine())
    val x1 = st1.nextToken().toLong()
    val y1 = st1.nextToken().toLong()
    val x2 = st1.nextToken().toLong()
    val y2 = st1.nextToken().toLong()

    val st2 = StringTokenizer(br.readLine())
    val x = st2.nextToken().toLong()
    val y = st2.nextToken().toLong()

    val dx = x2 - x1
    val dy = y2 - y1

    // If parity of dx and dy is different, impossible
    if ((abs(dx) + abs(dy)) % 2L != 0L) {
        println("NO")
        return
    }

    // Solve:
    // dx = x*(a - b) + y*(c - d)
    // dy = y*(a - b) + x*(c - d)
    // Let p = a - b, q = c - d
    // Then:
    // dx = x*p + y*q
    // dy = y*p + x*q

    val det = (x * x - y * y) // determinant of the system

    // If det == 0, special handling
    if (det == 0L) {
        // From equations: dx - dy = (x - y)(p + q)
        val diff = dx - dy
        val sum = dx + dy

        // Check if (x - y) divides diff and (x + y) divides sum
        val xMinusY = x - y
        val xPlusY = x + y

        var possible = false

        if (xMinusY != 0L && diff % xMinusY == 0L) {
            val s = diff / xMinusY // s = p + q
            // Now check if we can find integers a,b,c,d with p+q = s
            // and a,b,c,d >= 0. Since potion can be used infinite times,
            // we only need existence of integer p,q such that p+q = s.
            // But we must also satisfy dx,dy equations; with det=0,
            // they are dependent, so one equation is enough.
            // Already satisfied by construction.
            possible = true
        }

        if (!possible && xPlusY != 0L && sum % xPlusY == 0L) {
            val t = sum / xPlusY // t = p + q (alternative relation)
            possible = true
        }

        println(if (possible) "YES" else "NO")
        return
    }

    // General case: solve for p and q
    // Using Cramer's rule:
    // p = (dx*x - dy*y) / det
    // q = (dx*y - dy*x) / det

    val pNum = dx * x - dy * y
    val qNum = dx * y - dy * x

    if (pNum % det != 0L || qNum % det != 0L) {
        println("NO")
        return
    }

    val p = pNum / det
    val q = qNum / det

    // Now we need to check if there exist non-negative integers a,b,c,d
    // such that a - b = p and c - d = q.
    // This is always possible for any integers p,q:
    // take a = max(p,0), b = a - p; similarly for c,d.
    // So no further check is needed.

    println("YES")
}

