fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(br.readLine())
    val x1 = st.nextToken().toLong()
    val y1 = st.nextToken().toLong()
    val x2 = st.nextToken().toLong()
    val y2 = st.nextToken().toLong()

    st = StringTokenizer(br.readLine())
    val x = st.nextToken().toLong()
    val y = st.nextToken().toLong()

    val dx = x2 - x1
    val dy = y2 - y1

    // Check parity condition
    if ((dx + dy) % 2L != 0L) {
        println("NO")
        return
    }

    // Check reachability in terms of gcd
    val g = gcd(x, y)
    if (abs(dx) % g == 0L && abs(dy) % g == 0L) {
        println("YES")
    } else {
        println("NO")
    }
}

fun gcd(a: Long, b: Long): Long {
    var x = abs(a)
    var y = abs(b)
    while (y != 0L) {
        val t = x % y
        x = y
        y = t
    }
    return x
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.abs

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    var st = StringTokenizer(reader.readLine())
    val x1 = st.nextToken().toLong()
    val y1 = st.nextToken().toLong()
    val x2 = st.nextToken().toLong()
    val y2 = st.nextToken().toLong()

    st = StringTokenizer(reader.readLine())
    val x = st.nextToken().toLong()
    val y = st.nextToken().toLong()

    val dx = x2 - x1
    val dy = y2 - y1

    // If parity of dx or dy doesn't match parity of x or y, impossible
    if ((dx and 1L) != (x and 1L) || (dy and 1L) != (y and 1L)) {
        println("NO")
        return
    }

    // Solve:
    // dx = x*(a - b) + y*(c - d)
    // dy = y*(a + b) + x*(c + d)
    // Let:
    // p = a - b, q = c - d, r = a + b, s = c + d
    // Then:
    // dx = x*p + y*q
    // dy = y*r + x*s
    // Also:
    // a = (p + r)/2, b = (r - p)/2, c = (q + s)/2, d = (s - q)/2 must be integers >= 0
    //
    // From dx, dy we can derive p, q, r, s using linear combinations.
    // But easier: brute force small combinations is impossible (unbounded).
    //
    // Observed invariant:
    // Moves are:
    // (x, y), (x, -y), (-x, y), (-x, -y)
    // So any move changes x-coordinate by ±x and y-coordinate by ±y.
    // Therefore:
    // dx must be multiple of gcd(x, x) = x and dy multiple of gcd(y, y) = y.
    // But signs allow any integer multiple.
    //
    // So necessary: dx % x == 0 and dy % y == 0.
    // Also, number of steps in x-direction and y-direction must have same parity:
    // Because each move uses one x-step and one y-step simultaneously.
    //
    // Let nx = dx / x, ny = dy / y.
    // Each move contributes ±1 to nx and ±1 to ny.
    // So nx and ny must have same parity (sum of ±1's).
    //
    // Additionally, |nx| and |ny| must be achievable with same number of moves:
    // Let total moves = k. Then |nx| <= k and |ny| <= k and (k - |nx|) even, (k - |ny|) even.
    // This is possible iff |nx| and |ny| have same parity and |nx| <= k, |ny| <= k for some k.
    // Choose k = max(|nx|, |ny|), parity condition already ensures feasibility.

    if (dx % x != 0L || dy % y != 0L) {
        println("NO")
        return
    }

    val nx = dx / x
    val ny = dy / y

    if ((abs(nx) % 2L) != (abs(ny) % 2L)) {
        println("NO")
        return
    }

    println("YES")
}

