import java.util.StringTokenizer

fun main() {
    val br = System.`in`.bufferedReader()
    val st1 = StringTokenizer(br.readLine())
    val x1 = st1.nextToken().toLong()
    val y1 = st1.nextToken().toLong()
    val x2 = st1.nextToken().toLong()
    val y2 = st1.nextToken().toLong()

    val st2 = StringTokenizer(br.readLine())
    val x = st2.nextToken().toLong()
    val y = st2.nextToken().toLong()

    val dx = x2 - x1
    val dy = y2 - y1

    // Check parity: dx and dy must both be multiples of gcd(x, y)
    fun gcd(a: Long, b: Long): Long {
        var aa = kotlin.math.abs(a)
        var bb = kotlin.math.abs(b)
        while (bb != 0L) {
            val t = aa % bb
            aa = bb
            bb = t
        }
        return aa
    }

    val g = gcd(x, y)
    if (dx % g != 0L || dy % g != 0L) {
        println("NO")
        return
    }

    // Solve for integers a, b in:
    // a*x + b*y = dx
    // a*y - b*x = dy
    // This is equivalent to complex multiplication:
    // (a + bi)*(x + yi) = dx + dyi
    // We can derive:
    // a = (dx*x + dy*y) / (x*x + y*y)
    // b = (dy*x - dx*y) / (x*x + y*y)
    val denom = x * x + y * y

    val aNum = dx * x + dy * y
    val bNum = dy * x - dx * y

    if (aNum % denom != 0L || bNum % denom != 0L) {
        println("NO")
        return
    }

    println("YES")
}
